<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import GameIcon from './GameIcon.vue'
import CrossPlatformEvidence from './CrossPlatformEvidence.vue'
const props=defineProps<{ report:any; group:string; reportId:string }>()
const auditOpen=ref(false),auditPage=ref(1)
const unselected=computed(()=>(props.report.candidateAudit||[]).filter((r:any)=>!r.selected))
watch(()=>props.reportId,()=>{auditPage.value=1})
const labels:Record<string,string>={WECHAT:'微信',DOUYIN:'抖音',IOS:'iOS',GOOGLE_PLAY:'Google Play'}
const items=computed(()=>(props.report.items||[]).filter((r:any)=>props.group==='ALL'||(props.group==='DOMESTIC'?r.region==='CN':r.region!=='CN')))
const groups=computed(()=>props.report.portfolio?.length?[...props.report.portfolio].sort((a:any,b:any)=>['NEW_ENTRY','ACCELERATOR','EARLY_FLEX','RESEARCH_FLEX','BENCHMARK'].indexOf(a.group)-['NEW_ENTRY','ACCELERATOR','EARLY_FLEX','RESEARCH_FLEX','BENCHMARK'].indexOf(b.group)).map((g:any)=>({...g,items:items.value.filter((r:any)=>r.allocatedSlot===g.group)})):[{group:'LEGACY',label:'历史研究线索',items:items.value}])
const safeUrl=(v:unknown)=>typeof v==='string'&&/^https?:\/\//.test(v)?v:undefined
function exportList(){
 const text=`# 本周游戏研究线索标准列表\n\n报告 ${props.reportId}；观察窗 ${props.report.windowStart} — ${props.report.windowEnd}\n\n以下为待核研究线索，不是已通过纯IAA资格的正式推荐。来源名次变化不等于用户量增长。\n\n`+items.value.map((r:any)=>`## ${r.displayOrder}. ${r.name}\n\n- 平台 / 地区：${labels[r.platform]||r.platform} / ${r.region}\n- 来源：${r.sourceKey} / ${r.boardName} / ${r.authority}\n- 发行方：${r.developer||'来源未提供'}\n- 来源玩法分类：${r.family}（待实机核验）\n- 玩法依据：${r.gameplayEvidence?.label||'历史来源标签'}\n- 依据原文：${r.gameplayEvidence?.quote||'见冻结材料'}\n- 组合席位：${r.portfolioLabel||'历史规则'}\n- 入榜证据：${r.entryEvidence?JSON.stringify(r.entryEvidence):'旧报告未计算'}\n- 同榜增速：${r.momentum?JSON.stringify(r.momentum):'旧报告未计算'}\n- 跨平台判断与冻结证据：${r.crossPlatform?JSON.stringify(r.crossPlatform):'旧报告未计算'}\n- 机会假设：${r.opportunityHypothesis||'未核验'}\n- 最近观察日：${r.latestObservedDate||props.report.windowEnd}；截止日状态：${r.currentState||'见逐日证据'}\n- 补位依据：${r.researchSelectionReason||'严格机会席'}\n- 研究类型：${r.signalLabel||'待核研究'}\n- 入选研究理由：${r.whyNow}\n- 资格：纯IAA未知；${r.identityStatus}\n- 缺口：${r.gaps.join('；')}\n- 下一步：${r.nextAction}\n- 原始来源：${r.sourceUrl}\n\n| 日期 | 名次 | 观察ID | 材料SHA256 | 定位 |\n| --- | --- | --- | --- | --- |\n`+r.history.map((p:any)=>`| ${p.date} | ${p.rank==null?'缺失':p.rank} | ${p.evidence?.observation_id||'—'} | ${p.evidence?.raw_sha256||'—'} | ${(p.evidence?.evidence_locator||'—').replace(/\|/g,'\\|')} |`).join('\n')).join('\n\n')+`\n\n组合分配：${JSON.stringify(props.report.portfolio||[])}\n\n需补充数据：${JSON.stringify(props.report.dataRequirements||[])}\n\n规则：${props.report.policy}\n\n规则版本：${props.report.algorithmVersion}\n`;
 const u=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=`本周研究线索-${props.reportId}.md`;a.click();URL.revokeObjectURL(u)
}
</script>
<template>
 <section class="research-leads insight-panel" aria-label="本周研究线索标准列表">
  <div class="section-heading"><div><h2>本周研究线索 · 待核验</h2><p>{{report.windowStart}} — {{report.windowEnd}} · {{report.items?.length||0}} 项；与正式精选合计最多 5 项</p></div><el-button :disabled="!items.length" @click="exportList">导出标准列表</el-button></div>
  <el-alert title="以下是有榜单依据的研究顺序，不是纯IAA正式推荐。身份、实机和变现证据核验通过后，再决定是否选用。" type="warning" :closable="false"/>
  <p>{{report.diagnostic}}</p>
  <details v-if="report.platformDiagnostics"><summary>平台覆盖与筛选缺口（按榜单条目计）</summary><el-table :data="report.platformDiagnostics" size="small"><el-table-column label="平台"><template #default="{row}">{{labels[row.platform]||row.platform}}</template></el-table-column><el-table-column prop="boardCandidates" label="候选条目"/><el-table-column prop="confirmedIdentity" label="已关联身份"/><el-table-column prop="missingGameplay" label="缺少玩法依据"/><el-table-column prop="latestObservedDate" label="最新观察日" min-width="110"/><el-table-column prop="currentCandidates" label="截止日有记录"/><el-table-column prop="missingCurrent" label="截止日缺记录"/><el-table-column prop="selected" label="入选"/></el-table><a :href="`#/identity?date=${report.windowEnd}`">补齐产品关联与玩法证据 →</a></details>
  <template v-if="report.portfolio?.length">
   <p><b>先发现，再验证：</b>核心 4 席按 2 / 1 / 1 分配，第 5 席只增补早期机会；严格机会席不足时，研究补位最多补到 5 项。补位对象仍是待核线索，不等于纯IAA正式推荐。研究补位使用其他组的空席，下方目标数不可相加；合计最多5项，证据不足仍留空。</p>
   <div class="portfolio-grid"><div v-for="g in report.portfolio" :key="g.group"><b>{{g.label}}</b><strong>{{g.selected}} / {{g.target}}</strong><small>{{g.reason}}</small></div></div>
  </template>
  <div v-if="!items.length" class="empty">当前范围暂无符合条件的研究线索。</div>
  <template v-for="section in groups" :key="section.group">
  <h3 v-if="section.items.length" class="portfolio-heading">{{section.label}}</h3>
  <article v-for="row in section.items" :key="row.leadKey" class="lead-item">
   <div class="lead-head"><GameIcon :url="row.thumbnailUrl" :name="row.name" :size="48"/><div><h3><a :href="`#/products?date=${report.windowEnd}&platform=${row.platform}&q=${encodeURIComponent(row.name)}`">{{row.displayOrder}}. {{row.name}}</a></h3><p>{{labels[row.platform]||row.platform}} · {{row.region}} · {{row.family}}（来源依据，待核验） · {{row.developer||'发行方未提供'}}</p></div><el-tag type="warning">待核研究线索</el-tag></div>
   <div class="lead-facts"><span>{{row.signalLabel||'待核研究'}}</span><span>{{row.boardName}} · {{row.latestObservedDate||report.windowEnd}} #{{row.latestRank}}</span><span v-if="row.latestObservedDate && row.latestObservedDate!==report.windowEnd">截止日缺采，当前名次未知</span><span>观察 {{row.observationDays}} / 7 日</span><span>{{row.rankChange==null?'单日记录，增长未知':`首末名次 ${row.firstRank} → ${row.latestRank}`}}</span><span>纯IAA：未知</span></div>
   <details class="lead-details" :key="`${reportId}:${row.leadKey}`">
   <summary :aria-label="`${row.name}的推荐详情`"><span class="when-closed">展开详情</span><span class="when-open">收起详情</span><span class="detail-hint"> · 推荐理由、跨平台证据与研究建议</span></summary>
   <p v-if="row.researchSelectionReason"><b>研究补位依据：</b>{{row.researchSelectionReason}}</p><p v-if="row.gameplayEvidence"><b>玩法依据：</b>{{row.gameplayEvidence.label}} · {{row.gameplayEvidence.quote}}</p><p><b>为什么现在研究：</b>{{row.whyNow}}</p><p><b>缺口与反对理由：</b>{{row.gaps.join('；')}}</p><p><b>下一步：</b>{{row.nextAction}}</p>
   <CrossPlatformEvidence :value="row.crossPlatform"/>
   <template v-if="row.entryEvidence">
    <p><b>入榜边界：</b>{{row.entryEvidence.firstSeenIn28Days}} 首次观察（28 日窗口），距今 {{row.entryEvidence.ageDays}} 天。{{row.entryEvidence.reason}}。{{row.entryEvidence.meaning}}</p>
    <p><b>同榜速度：</b>前日上涨 {{row.momentum.previousDailyGain??'未知'}} 名，最新日上涨 {{row.momentum.latestDailyGain??'未知'}} 名；两日合计 {{row.momentum.twoDayGain??'未知'}} 名，加速度 {{row.momentum.acceleration??'未知'}}。可比样本 {{row.momentum.comparableCount}} 个，增幅顺序 {{row.momentum.withinChartOrder??'未知'}}（仅同榜；负数表示下降）。</p>
    <p><b>新赛道 / 新玩法：未核验。</b>{{row.opportunityHypothesis}}</p>
    <details><summary>入榜前完整 Top100 未出现的证据（{{row.entryEvidence.priorCompleteAbsence.length}} / 3 日）</summary><p v-if="!row.entryEvidence.priorCompleteAbsence.length">缺少足够完整基线，不能确认新增。</p><p v-for="e in row.entryEvidence.priorCompleteAbsence" :key="e.observation_id">{{e.business_date}} · 观察 {{e.observation_id}} · {{e.completeness}}<small>SHA256 {{e.raw_sha256}}</small><a v-if="safeUrl(e.source_url)" :href="safeUrl(e.source_url)" target="_blank" rel="noopener noreferrer">来源页面 ↗</a></p></details>
   </template>
   <details><summary>7日记录与证据 · {{row.authority==='THIRD_PARTY'?'第三方来源':'官方来源'}}</summary><p>{{row.identityStatus==='CONFIRMED_PRODUCT_ASSOCIATION'?'已确认统一产品关联；来源内历史匹配边界、身份依据见跨平台证据卡。':row.identityStatus==='SOURCE_LABEL_MATCH_UNVERIFIED'?'名称与发行方仅用于同来源内待核观察匹配；未建立平台身份、未跨平台合并。':'来源提供稳定ID；仍须核验当前版本与玩法。'}}</p><div class="table-wrap"><table><thead><tr><th>业务日</th><th>来源名次</th><th>观察 / 来源</th><th>材料定位</th></tr></thead><tbody><tr v-for="p in row.history" :key="p.date"><td>{{p.date}}</td><td>{{p.rank==null?'缺失 / 身份未确认':'#'+p.rank}}</td><td>{{p.evidence?`观察 ${p.evidence.observation_id}`:'无证据'}}<br/><a v-if="safeUrl(p.evidence?.source_url)" :href="safeUrl(p.evidence.source_url)" target="_blank" rel="noopener noreferrer">来源页面 ↗</a></td><td><template v-if="p.evidence"><code>{{p.evidence.evidence_locator}}</code><small>SHA256 {{p.evidence.raw_sha256}}</small><small>可用时间（UTC）{{p.evidence.available_at}} · {{p.evidence.completeness}}</small></template><span v-else>不以其他日期回填</span></td></tr></tbody></table></div><p v-if="row.contextualSignals.length">同来源其他榜单仅作背景（不重复计独立证据）：{{row.contextualSignals.map((s:any)=>`${s.boardName} #${s.rank}`).join('；')}}</p></details>
   </details>
  </article>
  </template>
  <details v-if="report.dataRequirements?.length"><summary>如何进一步判断新玩法、新赛道 · 需要补充的数据</summary><ul><li v-for="d in report.dataRequirements" :key="d.data"><b>{{d.priority}} · {{d.data}}</b><p>{{d.purpose}}<br/>获取现状：{{d.availability}}</p></li></ul></details>
  <details @toggle="auditOpen=($event.target as HTMLDetailsElement).open"><summary>透明选取规则与未选原因 · {{unselected.length}} 条</summary><p>{{report.policy}}</p><div v-if="auditOpen" class="table-wrap"><el-table :data="unselected.slice((auditPage-1)*20,auditPage*20)" max-height="360" size="small"><el-table-column prop="name" label="候选" min-width="180"/><el-table-column prop="boardName" label="来源榜单" width="140"/><el-table-column prop="entryEvidence.firstSeenIn28Days" label="28日内首次观察" width="140"/><el-table-column prop="opportunityAssessment" label="早期机会判断" min-width="280"/><el-table-column prop="exclusionReason" label="本期未选原因" min-width="320"/></el-table><el-pagination v-model:current-page="auditPage" :page-size="20" :total="unselected.length" layout="prev,pager,next"/></div><small>规则版本 {{report.algorithmVersion}}；有效来源快照 {{report.snapshotCount}} 份。记录随本期报告冻结。</small></details>
 </section>
</template>
<style scoped>
.lead-details>summary{list-style-position:inside}.lead-details>summary .when-open{display:none}.lead-details[open]>summary .when-open{display:inline}.lead-details[open]>summary .when-closed{display:none}.lead-details>summary:focus-visible{outline:2px solid #296ac0;outline-offset:3px}.detail-hint{color:#63748a;font-weight:normal}
.portfolio-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;margin:16px 0}.portfolio-grid>div{border:1px solid #dce6f4;padding:14px;background:#f8fbff}.portfolio-grid strong{display:block;font-size:24px;color:#2464a4;margin-top:10px}.portfolio-heading{padding:12px 0 0;color:#235b94}.research-leads{margin-top:20px}.research-leads h2{font-size:18px;margin:0}.research-leads p{line-height:1.8}.lead-item{border-top:1px solid #e3eaf4;padding:22px 0}.lead-head{display:flex;align-items:center;gap:12px}.lead-head h3{margin:0;font-size:18px}.lead-head p{margin:5px 0;color:#63748a;font-size:12px}.lead-head .el-tag{margin-left:auto}.lead-facts{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.lead-facts span{background:#f0f5fc;padding:6px 10px;font-size:12px;color:#375c8a}.research-leads summary{cursor:pointer;color:#296ac0;font-size:13px;padding:8px 0}.research-leads table{width:100%;border-collapse:collapse;font-size:12px;min-width:700px}.research-leads th,.research-leads td{text-align:left;padding:10px;border:1px solid #e1e8f2;vertical-align:top}.research-leads th{background:#f4f7fb;white-space:nowrap}.research-leads td code{overflow-wrap:anywhere}.research-leads small{display:block;color:#7d8ba0;margin-top:6px;overflow-wrap:anywhere}.research-leads .section-heading{gap:12px;flex-wrap:wrap}@media(max-width:650px){.lead-head{flex-wrap:wrap}.lead-head .el-tag{margin-left:0}.lead-head h3{font-size:16px}}
</style>
